    "app_intro": "MAX课程表是一款本地课程表工具，用于每日与每周排课、作息设置，以及主题和会员。课程、作息、主题和语言偏好默认只保存在您的设备上，不会上传到开发者自有服务器做账号同步。应用没有账号，也不需要登录。",
