    "wata_h1": "渡边记账",
    "wata_metaTitle": "渡边记账 — Sumiger",
    "wata_metaDesc": "渡边记账是一款本地记账工具，用于手动记账、按日查看收支，以及收支趋势与分类统计。数据默认只保存在您的设备上，不绑定微信、支付宝账号。",
    "wata_intro": "渡边记账是一款本地记账工具，用于手动记账、按日查看收支，以及收支趋势与分类统计。账本、分类和偏好默认只保存在您的设备上，不会上传到开发者自有服务器做账号同步。应用没有账号，也不需要登录，不绑定微信、支付宝账号。",
    "wata_authorTitle": "作者寄语",
    "wata_authorText": "渡边是日本的一个大姓，在日本社会深陷通缩时，出现了一群“渡边太太”。因国情不同，我们无法像“渡边太太”那样开源，但我们可以用渡边记账来节流。",
    "wata_featTitle": "功能",
    "wata_featHome": "<strong>首页：</strong>左右滑切换列表和日历。列表按日期分组，顶部可换月份，显示当月收入、支出和余额；日历按天显示结余，正数为绿色、负数为红色，点某天看当天明细。右下角加号可记一笔：金额、收/支、分类、商户/对方、备注、支付方式。",
    "wata_featCharts": "<strong>图表：</strong>顶部切换饼状图和折线图，两张图都能切换支出和收入。饼状图按分类显示占比和金额；折线图显示按日趋势，下面是日期、收入、支出、结余的表，带总计行。",
    "wata_featSettings": "<strong>设置：</strong>作者寄语、联系方式、隐私政策和开发者个人网站。联系方式：<a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>。",
    "wata_expTitle": "实验功能（默认关闭）",
    "wata_expIntro": "以下两个功能是实验性的，默认关闭，打开后也只把结果放进“待确认”，由您逐条核对金额、改好分类，点“保存入账”才会写入账本。可能会漏记、错记，随时可能下线。",
    "wata_expImport": "<strong>账单导入：</strong>您自己从微信、支付宝官方入口导出账单文件（.csv），再分享给应用解析。微信账单只能导出最近三个月。解析结果去重后进“待确认”，不自动入账。",
    "wata_expListener": "<strong>通知监听（仅安卓）：</strong>只读微信和支付宝的支付通知，在本机解析金额和商户名，不存通知原文，验证码一律丢弃。需要在系统设置里由您亲自授予“通知使用权”，应用不能自己授权。",
    "wata_notDo": "不做：月预算、绑定微信/支付宝账号实时同步、读屏增强、截图识别、云同步、社区分享、图片上传。",
    "wata_dlTitle": "下载",
    "wata_dlHM": "下载安装包（鸿蒙，1.0.1，199 KB）",
    "wata_dlHMNote": "此安装包为鸿蒙版（.app），适用于鸿蒙设备。应用市场审核通过后，也可从华为应用市场下载。",
    "wata_dlAn": "下载安装包（安卓，1.0.0，7.4 MB）",
    "wata_dlAnNote": "此安装包为安卓版（.apk），适用于安卓手机，安装时需允许安装未知来源应用。",
    "wata_privTitle": "隐私",
    "wata_privText": "账本数据只存在您的设备上。实验功能打开前会再弹一次确认，说明读什么、存哪、怎么关；关闭后立即停止读取，已入账的不受影响。识别记录只留最近 24 小时、最多 50 条，可一键清除。完整隐私政策见应用内的隐私政策页。",
