    "wapp_metaTitle": "渡边记账隐私政策 — Sumiger",
    "wapp_metaDesc": "渡边记账的隐私政策。账本数据默认只保存在您的设备上，不会上传。",
    "wapp_h1": "渡边记账隐私政策",
    "wapp_intro1": "本政策说明本地记账工具渡边记账如何处理信息。它用于手动记账、按日查看收支，以及查看收支趋势与分类统计。应用没有账号体系，不需要登录，不绑定任何支付账号。",
    "wapp_intro2": "实验功能（账单导入、通知监听）默认关闭，打开后也只把结果放进“待确认”，由您逐条核对后才会写入账本。相关说明见“实验功能”一节。",
    "wapp_tocInfo": "我们处理的信息",
    "wapp_tocExp": "实验功能",
    "wapp_tocPerm": "权限",
    "wapp_tocNot": "当前版本不涉及",
    "wapp_tocStore": "存储与保留",
    "wapp_tocShare": "共享、转让与公开披露",
    "wapp_tocRights": "您的权利",
    "wapp_tocUpdate": "本政策如何更新",
    "wapp_infoP": "记账内容、分类和偏好默认只保存在您的设备上，不会上传到开发者自有服务器做账号同步。开发者没有这些内容的服务器副本。",
    "wapp_ib1t": "记账内容",
    "wapp_ib1s": "用于记录金额、收或支、分类、商户或对方、备注、支付方式和日期。只保存在您的设备上。",
    "wapp_ib2t": "分类与偏好",
    "wapp_ib2s": "用于在本机保存分类、显示与语言设置。只保存在您的设备上。",
    "wapp_ib3t": "识别记录",
    "wapp_ib3s": "实验功能产生的识别结果说明，见“实验功能”一节。只保存在您的设备上。",
    "wapp_expP": "以下两项是实验功能，默认关闭。打开后结果只进“待确认”，由您逐条核对金额、改好分类，点“保存入账”才会写入账本。识别可能漏记或错记，功能随时可能调整或下线。",
    "wapp_exp1t": "账单导入",
    "wapp_exp1s": "只有您主动选择账单文件（CSV）时，应用才会在本机解析其中的交易时间、类型、对方、商品、收或支、金额、支付方式、状态和单号。文件不上传。微信账单只能导出最近三个月。支付宝账单表头未用真实文件核对过，解析结果请逐条核对。",
    "wapp_exp2t": "通知监听（仅安卓）",
    "wapp_exp2s": "只读微信和支付宝的支付通知，在本机解析金额和商户名。验证码一律丢弃，长数字只留后四位，不保存通知原文。需要在系统设置里由您亲自授予通知使用权，应用不能自己授权。",
    "wapp_exp3t": "待确认与识别记录",
    "wapp_exp3s": "导入和通知的结果都先停在“待确认”，保存入账之前不会写入账本。识别记录只留最近 24 小时、最多 50 条，可一键清除，超时或超量自动删除。",
    "wapp_permP": "应用只使用功能实际需要的系统能力。",
    "wapp_permLi1": "通知使用权：仅在您打开通知监听后使用，用于读取微信和支付宝的支付通知。",
    "wapp_permLi2": "文件访问：只在您通过系统选择器主动选取账单文件时访问对应文件。应用不会在您未选取时扫描文件系统。",
    "wapp_notP1": "当前版本不涉及应用内广告或个性化推荐，不接入第三方统计或广告 SDK。",
    "wapp_notP2": "应用不主动收集通讯录、精确位置、短信内容或传感器数据，也不为画像目的收集 IMEI 或 OAID。",
    "wapp_storeP": "上述信息保存在您的设备上，在实现相应功能所需的期间内保留，直到您删除记录、卸载应用或清除应用数据。识别记录只留最近 24 小时、最多 50 条。",
    "wapp_shareP1": "开发者不出售个人信息，也不会为账号同步把账本、分类、偏好或识别记录上传到开发者自有服务器。",
    "wapp_shareP2": "法律法规有强制性要求时，开发者仅在该要求的范围内处理。",
    "wapp_rightsLi1": "查阅与更正：在应用内查看和编辑记账内容与设置。",
    "wapp_rightsLi2": "删除：删除单条记录，或卸载应用、清除应用数据。",
    "wapp_rightsP": "开发者没有这些内容的服务器副本，因此删除以您设备上的操作为准。如需咨询，请使用<a href='#contact'>文末邮箱</a>。",
    "wapp_childP1": "本应用不主动收集未满 14 周岁儿童的个人信息。未满 18 周岁的未成年人，请在监护人同意和指导下使用。",
    "wapp_updateP": "政策如有变更，会更新本页面，并修改「更新日期」。请以本页面显示的日期为准。",
