    "wterms_tocLaw": "法律与联系",
    "wterms_serviceP": "渡边记账是一款本地记账工具，提供手动记账、按日查看收支、收支趋势与分类统计。实验功能包括账单导入与通知监听，见“实验功能”一节。",
    "wterms_serviceLi1": "首页：列表与日历两种视图，查看当月收入、支出、余额与每天结余。",
    "wterms_serviceLi2": "图表：饼状图与折线图，均可切换支出与收入查看。",
    "wterms_serviceLi3": "设置：作者寄语、联系方式、隐私政策与开发者个人网站。",
    "wterms_dataP1": "本应用没有账号体系，不需要登录，不绑定任何支付账号。",
    "wterms_dataP2": "账本数据默认只保存在您的设备上，开发者没有服务器副本。请自行妥善保管。因卸载应用、清除应用数据、更换或丢失设备、设备故障导致的数据丢失，开发者不承担责任。",
    "wterms_expP1": "账单导入与通知监听是实验功能，默认关闭。打开后结果只进“待确认”，由您逐条核对金额、改好分类，点“保存入账”才会写入账本。",
    "wterms_expP2": "识别可能漏记或错记，功能随时可能调整或下线。开发者不对识别结果的准确性负责，请以您核对后的入账记录为准。",
    "wterms_rulesLi1": "不得将本应用用于任何违法用途，包括但不限于记录违法交易、洗钱、逃税。",
    "wterms_rulesLi2": "不得对应用进行逆向工程、破解、篡改，或干扰其正常运行。",
    "wterms_rulesLi3": "不得冒充开发者，或以开发者的名义对外提供服务。",
    "wterms_feeP": "本应用目前全部免费，不收取任何费用。以后如有收费功能，会提前说明，由您自主选择是否开通，不会在您不知情的情况下扣费。",
    "wterms_disP1": "本应用只做记账记录，不构成财务、税务、投资或法律建议。",
    "wterms_disP2": "因设备故障、系统问题或实验功能识别错误造成的记录问题，请以您的原始凭证为准，开发者不承担相应责任。",
    "wterms_ipP": "本应用及其内容（包括名称、界面、文字说明）的知识产权归开发者所有。未经许可，不得复制、分发、修改或用于商业用途。",
    "wterms_changeP": "开发者可根据需要更新版本、调整或下线功能，更新内容会在应用内或网站说明。您可以随时停止使用并卸载应用。",
    "wterms_minorsP": "未满 14 周岁请在监护人同意和指导下使用；未满 18 周岁的未成年人，请在监护人指导下使用。",
