    "ch_intro": "本说明供未满 14 周岁儿童的监护人阅读，说明 MAX课程表如何对待儿童个人信息。本页可以单独阅读。完整政策见 <a href='../'>MAX课程表隐私政策</a>。",
    "ch_scopeTitle": "适用范围",
    "ch_scopeP1": "本说明适用于未满 14 周岁的儿童及其监护人。未满 18 周岁的未成年人，请在监护人指导下使用本应用。",
    "ch_scopeP2": "MAX课程表是本地课程表工具，用于每日和每周排课、作息设置，以及主题和会员。应用没有账号体系，不需要登录。",
