    "rts_metaTitle": "MAX课程表隐私权利 — Sumiger",
    "rts_metaDesc": "MAX课程表用户隐私权利说明：查阅、更正、删除本地数据的方法，以及如何通过邮件行使权利。课程、作息和偏好默认只保存在您的设备上。",
    "rts_h1": "MAX课程表隐私权利",
    "rts_intro": "本页说明您对 MAX课程表处理的信息享有的权利，以及如何行使这些权利。MAX课程表没有账号体系，不需要登录；课程、作息、主题和偏好默认只保存在您的设备上，开发者没有服务器副本。完整说明见<a href='../'>MAX课程表隐私政策</a>。",
    "rts_rLi1": "查阅与更正：在应用内查看、编辑课程和设置。",
    "rts_rLi2": "删除：卸载应用，或清除应用数据。",
    "rts_rLi3": "停止使用：应用没有账号，不用登录；如您不同意本政策或不希望继续使用，请停止使用本应用，或卸载应用以删除本地数据。",
    "rts_rLi4": "申诉与咨询：如您对本政策或应用处理信息的方式有疑问、异议或申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，在邮件中说明您是本人还是监护人、涉及的问题以及希望如何处理，开发者会通过邮件回复。",
    "rts_rNote": "开发者没有这些内容的服务器副本，因此删除以您设备上的卸载或清除应用数据为准，开发者无法从服务器端代您删除；查阅与更正请在设备上的应用内完成。",
    "rts_howTitle": "如何行使权利",
    "rts_howLi1": "查阅、更正：打开应用，在课表页编辑相应课程，或在设置页修改作息与偏好。",
    "rts_howLi2": "删除单项内容：在应用内删除相应课程。",
    "rts_howLi3": "删除全部本地数据：卸载应用；或在系统设置中找到 MAX课程表，清除应用数据。卸载或清除数据后，设备上的本地数据即被删除，请在操作前自行确认是否需要保留课表内容。",
    "rts_howLi4": "联系开发者：如需咨询、申诉，或对上述操作有疑问，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，写明涉及的问题以及希望如何处理（查阅、更正、删除或停止使用）。",
    "rts_childP1": "本应用不主动收集未满 14 周岁儿童的个人信息。未满 18 周岁的未成年人，请在监护人指导下使用。",
    "rts_childP2": "监护人申诉与删除指引：监护人如对儿童使用本应用有疑问、异议或申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，邮件标题请注明“监护人申诉”，并写明儿童年龄、涉及的问题以及希望如何处理（查阅、更正、删除或停止使用），开发者会通过邮件回复操作指引。",
    "rts_childP3": "删除本地数据的方法（请在儿童的设备上操作）：在应用内删除相应课程；或卸载应用，或在系统设置中清除应用数据。开发者没有服务器副本，无法远程查看、导出或删除儿童设备上的数据，删除须由监护人在设备上完成。",

