    "app_subText": "鴻蒙版主題會員 ¥3/月，每月自動續期，透過華為應用程式內購買開通，可隨時取消。安卓版主題已全部解鎖，不涉及付費訂閱。詳見<a href='../../subscription/'>訂閱說明</a>。",
    "app_privTitle": "隱私",
    "app_childTitle": "兒童個人資訊保護說明",
    "app_childNote": "未滿 14 週歲",

    "wata_h1": "渡邊記帳",
    "wata_metaTitle": "渡邊記帳 — Sumiger",
    "wata_metaDesc": "渡邊記帳是一款本地記帳工具，用於手動記帳、按日查看收支，以及收支趨勢與分類統計。資料預設只儲存在您的裝置上，不綁定微信、支付寶帳號。",
    "wata_intro": "渡邊記帳是一款本地記帳工具，用於手動記帳、按日查看收支，以及收支趨勢與分類統計。帳本、分類和偏好預設只儲存在您的裝置上，不會上傳到開發者自有伺服器做帳號同步。應用程式沒有帳號，也不需要登入，不綁定微信、支付寶帳號。",
    "wata_authorTitle": "作者寄語",
    "wata_authorText": "渡邊是日本的一個大姓，在日本社會深陷通縮時，出現了一群「渡邊太太」。因國情不同，我們無法像「渡邊太太」那樣開源，但我們可以用渡邊記帳來節流。",
    "wata_featTitle": "功能",
    "wata_featHome": "<strong>首頁：</strong>左右滑切換清單和日曆。清單按日期分組，頂部可換月份，顯示當月收入、支出和餘額；日曆按天顯示結餘，正數為綠色、負數為紅色，點某天看當天明細。右下角加號可記一筆：金額、收/支、分類、商家/對方、備註、支付方式。",
    "wata_featCharts": "<strong>圖表：</strong>頂部切換圓餅圖和折線圖，兩張圖都能切換支出和收入。圓餅圖按分類顯示占比和金額；折線圖顯示按日趨勢，下面是日期、收入、支出、結餘的表，帶總計行。",
    "wata_featSettings": "<strong>設定：</strong>作者寄語、聯絡方式、隱私政策和開發者個人網站。聯絡方式：<a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>。",
    "wata_expTitle": "實驗功能（預設關閉）",
    "wata_expIntro": "以下兩個功能是實驗性的，預設關閉，開啟後也只把結果放進「待確認」，由您逐條核對金額、改好分類，點「儲存入帳」才會寫入帳本。可能會漏記、錯記，隨時可能下線。",
    "wata_expImport": "<strong>帳單匯入：</strong>您自己從微信、支付寶官方入口匯出帳單檔案（.csv），再分享給應用程式解析。微信帳單只能匯出最近三個月。解析結果去重後進「待確認」，不自動入帳。",
    "wata_expListener": "<strong>通知監聽（僅限安卓）：</strong>只讀微信和支付寶的支付通知，在本機解析金額和商家名稱，不存通知原文，驗證碼一律丟棄。需要在系統設定裡由您親自授予「通知使用權」，應用程式不能自己授權。",
    "wata_notDo": "不做：月預算、綁定微信/支付寶帳號即時同步、讀屏增強、截圖辨識、雲端同步、社群分享、圖片上傳。",
    "wata_dlTitle": "下載",
    "wata_dlHM": "下載安裝包（鴻蒙，1.0.1，199 KB）",
    "wata_dlHMNote": "此安裝包為鴻蒙版（.app），適用於鴻蒙裝置。應用程式市場審核通過後，也可從華為應用程式市場下載。",
    "wata_dlAn": "下載安裝包（安卓，1.0.0，7.4 MB）",
    "wata_dlAnNote": "此安裝包為安卓版（.apk），適用於安卓手機，安裝時需允許安裝未知來源應用程式。",
    "wata_privTitle": "隱私",
    "wata_privText": "帳本資料只存在您的裝置上。實驗功能開啟前會再彈一次確認，說明讀什麼、存哪、怎麼關；關閉後立即停止讀取，已入帳的不受影響。辨識記錄只留最近 24 小時、最多 50 條，可一鍵清除。完整隱私政策見應用程式內的隱私政策頁。",
    "wata_privLink": "渡邊記帳隱私政策",
    "wata_termsLink": "渡邊記帳用戶協議",

    "sub_metaTitle": "MAX課程表訂閱說明 — Sumiger",
