    "sub_appliesVal": "鴻蒙版。安卓版主題已全部解鎖，不涉及付費訂閱。",
    "sub_lede": "<strong>一句話說明：主題會員 ¥3/月，每月自動續期。</strong>開通後每月透過您的華為帳號自動扣費 ¥3，直到您取消為止。取消後目前已付費的週期結束前仍可正常使用，到期後不再扣費。",
    "sub_priceNote": "購買時請以應用程式內購買頁與華為收銀台顯示的金額和週期為準。本頁說明與應用程式內購買頁、華為收銀台顯示不一致的，以購買時顯示的為準。",
    "sub_tocTitle": "目錄",
    "sub_tocWhat": "訂閱內容",
