    "sub_tocRefund": "退款",
    "sub_tocMinors": "未成年人",
    "sub_tocContact": "聯絡我們",
    "sub_whatP1": "主題會員用於開通 MAX課程表鴻蒙版的主題會員權益，開通後可使用主題會員專屬主題。課程表的基本功能（每日與每週排課、作息設定）不依賴訂閱，免費可用。",
    "sub_whatP2": "安卓版主題已全部解鎖，不需要開通訂閱，也不涉及付費。",
    "sub_pb1t": "價格：¥3/月",
    "sub_pb1s": "每個訂閱週期為 1 個月，費用為 ¥3。",
    "sub_pb2t": "自動續期",
    "sub_pb2s": "訂閱到期後會自動續期 1 個月，並透過您的華為帳號綁定的支付方式自動扣費 ¥3，除非您在下個週期開始前取消。",
    "sub_pb3t": "扣費方",
    "sub_pb3s": "扣費由華為應用程式內購買處理。開發者不收集、不儲存您的銀行卡號等支付資訊。",
    "sub_pb4t": "取消後",
    "sub_pb4s": "取消自動續期後，已付費的目前週期結束前仍可正常使用主題會員權益，到期後權益停止，不再扣費。",
    "sub_buyP1": "在鴻蒙版 MAX課程表中，開啟主題頁或會員頁，點選「開通主題會員」，在購買頁確認價格（¥3/月）與自動續期說明，勾選同意本訂閱說明後，在華為收銀台確認付款即可開通。",
    "sub_buyP2": "購買頁的同意選項預設不勾選，需要您自行勾選。如果支付失敗或您在收銀台取消支付，不會開通會員，也不會扣費。",
    "sub_cancelP1": "隨時可以取消自動續期，取消不設額外條件。任選以下一種方式：",
    "sub_cb1t": "方式 1：在手機設定中取消",
    "sub_cb1s": "開啟手機「設定」，點選頂部的華為帳號頭像，進入「付款與帳單」，點選「訂閱」，找到 MAX課程表，按提示取消訂閱。",
    "sub_cb2t": "方式 2：在華為應用程式市場中取消",
    "sub_cb2s": "開啟華為應用程式市場，點選「我的」，點選頂部的頭像，進入「帳戶中心 > 付款與帳單 > 訂閱/免密支付」，找到 MAX課程表，按提示取消訂閱。",
    "sub_cb3t": "方式 3：在應用程式內取消",
    "sub_cb3s": "在 MAX課程表鴻蒙版的會員頁，找到管理訂閱或取消訂閱入口，按提示操作。",
    "sub_cancelNote1": "請注意：只解除安裝應用程式不會取消訂閱。解除安裝後訂閱仍會繼續自動續期，如需停止扣費，請按上面的方式先取消訂閱。",
    "sub_cancelNote2": "取消後如需確認是否已取消成功，可按方式 1 或方式 2 的路徑，查看 MAX課程表的訂閱狀態與到期日。",
    "sub_refundP": "退款請透過華為申請：在華為應用程式市場「我的 > 訂單/退款」中提交，或聯絡華為客服，按華為的規則處理。款項按華為的規則原路退回，對應的會員權益同時撤銷。",
    "sub_minorsP1": "未滿 18 週歲的未成年人開通主題會員，須由監護人決定並完成支付。監護人如有疑問，請發電子郵件到<a href='#contact'>文末信箱</a>聯絡開發者。",
    "sub_minorsP2": "未滿 14 週歲兒童的個人資訊保護說明，見<a href='../privacy/max-timetable/children/'>兒童個人資訊保護說明</a>。",
    "sub_contactP": "購買、續費或取消遇到問題，請發電子郵件聯絡開發者，郵件中請說明遇到的問題；涉及華為訂單的問題，請同時提供華為訂單編號。",
