    "papp_metaTitle": "MAX課程表隱私政策 — Sumiger",
    "papp_metaDesc": "MAX課程表的隱私政策。課程、作息和偏好預設只儲存在您的裝置上。目前版本不涉及應用程式內廣告或個人化推薦。",
    "papp_pkgName": "套件名稱",
    "papp_intro1": "本政策說明本地課程表工具 MAX課程表如何處理資訊。它可以用來安排每日和每週的課程、設定作息，以及使用主題和會員。應用程式沒有帳號體系，不需要登入。",
    "papp_intro2": "未滿 14 週歲兒童的說明另有單獨頁面：<a href='children/'>兒童個人資訊保護說明</a>。本政策中也有一節可供頁內查閱，見<a href='#children'>未成年人</a>。",
    "papp_tocInfo": "我們處理的資訊",
    "papp_tocNot": "目前版本不涉及",
    "papp_tocPerm": "權限",
    "papp_tocStore": "儲存與保留",
    "papp_tocShare": "共享、轉讓與公開揭露",
    "papp_tocRights": "您的權利",
    "papp_tocUpdate": "本政策如何更新",
    "papp_infoP": "課程、作息、主題和語言偏好預設只儲存在您的裝置上，不會上傳到開發者自有伺服器做帳號同步。開發者沒有這些內容的伺服器副本。",
    "papp_ib1t": "課程與作息",
    "papp_ib1s": "用於在本機安排每日和每週的課程，並儲存作息。只儲存在您的裝置上。",
    "papp_ib2t": "主題與語言偏好",
    "papp_ib2s": "用於在本機儲存顯示設定。只儲存在您的裝置上。",
    "papp_ib3t": "您主動選擇的照片",
    "papp_ib3s": "用於課程表圖片匯入或 DIY 背景。只有您透過系統選擇器選取時，應用程式才會存取對應照片，並儲存在您的裝置上。",
    "papp_ib4t": "您主動選擇的文件",
    "papp_ib4s": "用於匯入 PDF、TXT 或 DOC 課程表檔案。只有您透過系統選擇器選取時，應用程式才會存取對應檔案，並儲存在您的裝置上。",
    "papp_ib5t": "本地提醒",
    "papp_ib5s": "用於課前在本機提醒。提醒內容留在您的裝置上。",
    "papp_ib6t": "主題會員",
    "papp_ib6s": "如涉及付費，由華為應用程式內購買（Huawei In-App Purchases，IAP）處理。開發者不收集銀行卡號。",
    "papp_notP1": "目前版本不涉及應用程式內廣告或個人化推薦。",
    "papp_notP2": "應用程式不主動收集通訊錄、精確位置或感測器資料，也不會為了建立用戶畫像而收集 IMEI 或 OAID。",
    "papp_permP": "應用程式只使用功能實際需要的系統能力。",
    "papp_permLi1": "通知權限用於課前提醒。",
    "papp_permLi2": "相簿和檔案只在您透過系統選擇器主動選取照片或文件時存取。應用程式不會在您未選取時掃描相簿或檔案系統。",
    "papp_storeP": "上述資訊儲存在您的裝置上，在實現相應功能所需的期間內保留，直到您解除安裝應用程式或清除應用程式資料。",
    "papp_shareP1": "開發者不出售個人資訊，也不會為帳號同步把課程、作息、偏好或您選取的照片和文件上傳到開發者自有伺服器。",
    "papp_shareP2": "主題會員如涉及付費，由華為應用程式內購買（Huawei In-App Purchases，IAP）處理。開發者不收集銀行卡號。",
    "papp_shareP3": "法律法規有強制性要求時，開發者僅在該要求的範圍內處理。",
    "papp_rightsLi1": "查閱與更正：在應用程式內編輯課程和設定。",
    "papp_rightsLi2": "刪除：解除安裝應用程式，或清除應用程式資料。",
    "papp_rightsP": "開發者沒有這些內容的伺服器副本，因此刪除以您裝置上的解除安裝或清除應用程式資料為準。如需諮詢，請使用<a href='#contact'>文末信箱</a>。",
    "papp_childP1": "本應用程式不主動收集未滿 14 週歲兒童的個人資訊。未滿 18 週歲的未成年人，請在監護人指導下使用。",
    "papp_childP2": "監護人可以使用<a href='#contact'>文末信箱</a>聯絡開發者。單獨頁面：<a href='children/'>兒童個人資訊保護說明</a>。",
    "papp_updateP": "政策如有變更，會更新本頁面，並修改「更新日期」。請以本頁面顯示的日期為準。",
