    "app_metaTitle": "MAX课程表 — Sumiger",
    "app_metaDesc": "MAX课程表是个本地课程表工具，用来排每日搭仔每周个课、设置作息，搭仔主题搭仔会员。",
    "app_devLine": "开发者 孙明威 / Sumiger",
    "app_intro": "MAX课程表是个本地课程表工具，用来排每日搭仔每周个课、设置作息，搭仔主题搭仔会员。课程、作息、主题搭仔语言偏好默认只保存在侬个设备上，勿会上传到开发者自家个服务器做账号同步。应用呒没账号，也勿需要登录。",
    "app_dlTitle": "下载",
    "app_dlHM": "下载安装包（鸿蒙，1.1.1，1.2 MB）",
    "app_dlHMNote": "搿个安装包是华为应用市场正式签名版（.app），适用勒鸿蒙设备。假使下载之后提示装勿上，请等应用市场审核通过之后再从华为应用市场下载。",
    "app_dlAn": "下载安装包（安卓，1.1.1，45.4 MB）",
    "app_dlAnNote": "搿个安装包是安卓版（.apk），适用勒安卓手机，安装个辰光要允许安装勿知来源个应用。安卓版主题已经全部解锁，乃歇支持拍照导入课表（本地识别）。",
    "app_subTitle": "订阅",
    "app_subText": "鸿蒙版主题会员 ¥3/月，每月自动续期，通过华为应用内支付开通，随时可以取消。安卓版主题已经全部解锁，勿涉及付费订阅。详情看<a href='../../subscription/'>订阅说明</a>。",
    "app_privTitle": "隐私",
    "app_childTitle": "儿童个人信息保护说明",
    "app_childNote": "未满 14 周岁",

    "wata_h1": "渡边记账",
    "wata_metaTitle": "渡边记账 — Sumiger",
    "wata_metaDesc": "渡边记账是个本地记账工具，用来手动记账、逐日看收支，搭仔收支趋势搭仔分类统计。数据默认只保存在侬个设备上，勿绑定微信、支付宝账号。",
    "wata_intro": "渡边记账是个本地记账工具，用来手动记账、逐日看收支，搭仔收支趋势搭仔分类统计。账本、分类搭仔偏好默认只保存在侬个设备上，勿会上传到开发者自家个服务器做账号同步。应用呒没账号，也勿需要登录，勿绑定微信、支付宝账号。",
    "wata_authorTitle": "作者寄语",
    "wata_authorText": "渡边是日本个一个大姓，日本社会深陷通缩个辰光，出现了一帮“渡边太太”。因为国情勿一样，我伲呒办法像“渡边太太”搿能开源，不过我伲可以用渡边记账来节流。",
    "wata_featTitle": "功能",
    "wata_featHome": "<strong>首页：</strong>左右滑切换列表搭仔日历。列表按日期分组，顶部好换月份，显示当月收入、支出搭仔余额；日历按日显示结余，正数是绿色、负数是红色，点某日看当天明细。右下角加号好记一笔：金额、收/支、分类、商户/对方、备注、支付方式。",
    "wata_featCharts": "<strong>图表：</strong>顶部切换饼状图搭仔折线图，两张图侪好切换支出搭仔收入。饼状图按分类显示占比搭仔金额；折线图显示按日趋势，下头是日期、收入、支出、结余个表，带总计行。",
    "wata_featSettings": "<strong>设置：</strong>作者寄语、联系方式、隐私政策搭仔开发者个人网站。联系方式：<a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>。",
    "wata_expTitle": "实验功能（默认关闭）",
    "wata_expIntro": "下头两个功能是实验性个，默认关闭，打开之后也只拿结果放进“待确认”，由侬逐条核对金额、改好分类，点“保存入账”才会写入账本。可能会漏记、错记，随时可能下线。",
    "wata_expImport": "<strong>账单导入：</strong>侬自家从微信、支付宝官方入口导出账单文件（.csv），再分享给应用解析。微信账单只好导出最近三个月。解析结果去重之后进“待确认”，勿自动入账。",
    "wata_expListener": "<strong>通知监听（只有安卓）：</strong>只读微信搭仔支付宝个支付通知，勒本机解析金额搭仔商户名，勿存通知原文，验证码一律丢弃。要勒系统设置里由侬亲自授予“通知使用权”，应用勿能自家授权。",
    "wata_notDo": "勿做：月预算、绑定微信/支付宝账号实时同步、读屏增强、截图识别、云同步、社区分享、图片上传。",
    "wata_dlTitle": "下载",
    "wata_dlHM": "下载安装包（鸿蒙，1.0.1，199 KB）",
    "wata_dlHMNote": "搿个安装包是鸿蒙版（.app），适用勒鸿蒙设备。应用市场审核通过之后，也好从华为应用市场下载。",
    "wata_dlAn": "下载安装包（安卓，1.0.0，7.4 MB）",
    "wata_dlAnNote": "搿个安装包是安卓版（.apk），适用勒安卓手机，安装个辰光要允许安装勿知来源个应用。",
    "wata_privTitle": "隐私",
    "wata_privText": "账本数据只存在侬个设备上。实验功能打开之前会再弹一次确认，讲明白读啥、存勒哪能、哪能关；关闭之后立刻停止读取，已经入账个勿受影响。识别记录只留最近 24 小时、顶多 50 条，好一键清除。完整隐私政策看应用里向个隐私政策页。",
    "wata_privLink": "渡边记账隐私政策",
    "wata_termsLink": "渡边记账用户协议",

