    "sub_lede": "<strong>一句话讲清爽：主题会员 ¥3/月，每月自动续期。</strong>开通之后每月通过侬个华为账号自动扣费 ¥3，直到侬取消为止。取消之后，搿个已经付过费个周期结束之前还可以正常用，到期之后就勿再扣费。",
    "sub_priceNote": "买个辰光请以应用内购买页搭仔华为收银台显示个金额搭仔周期为准。搿页个说明搭仔应用内购买页、华为收银台显示个勿一样个，以买个辰光显示个为准。",
