    "sub_whatP1": "主题会员是用来开通 MAX课程表鸿蒙版个主题会员权益，开通之后可以用主题会员专属主题。课程表个基本功能（每日搭仔每周排课、作息设置）勿靠订阅，免费就可以用。",
    "sub_whatP2": "安卓版主题已经全部解锁，勿需要开通订阅，也勿涉及付费。",
    "sub_pb1t": "价格：¥3/月",
    "sub_pb1s": "每个订阅周期是 1 个月，费用是 ¥3。",
    "sub_pb2t": "自动续期",
    "sub_pb2s": "订阅到期之后会自动续期 1 个月，并通过侬个华为账号绑定个支付方式自动扣费 ¥3，除非侬勒下个周期开始之前取消。",
    "sub_pb3t": "扣费方",
    "sub_pb3s": "扣费由华为应用内支付处理。开发者勿收集、勿存储侬个银行卡号等支付信息。",
    "sub_pb4t": "取消之后",
    "sub_pb4s": "取消自动续期之后，已经付过费个搿个周期结束之前还可以正常用主题会员权益，到期之后权益停止，勿再扣费。",
    "sub_buyP1": "勒鸿蒙版 MAX课程表里向，打开主题页或者会员页，点“开通主题会员”，勒购买页确认价格（¥3/月）搭仔自动续期说明，勾选同意搿份订阅说明之后，勒华为收银台确认付款就可以开通。",
    "sub_buyP2": "购买页个同意选项默认是勿勾选个，要侬自家勾选。假使支付失败或者侬勒收银台取消支付，勿会开通会员，也勿会扣费。",
    "sub_cancelP1": "随时可以取消自动续期，取消呒没啥额外条件。随便选下底一种方式：",
    "sub_cb1t": "方式 1：手机设置里向取消",
    "sub_cb1s": "打开手机“设置”，点顶部个华为账号头像，进入“付款与账单”，点“订阅”，寻着 MAX课程表，按提示取消订阅。",
    "sub_cb2t": "方式 2：华为应用市场里向取消",
    "sub_cb2s": "打开华为应用市场，点“我个”，点顶部个头像，进入“账户中心 > 付款与账单 > 订阅/免密支付”，寻着 MAX课程表，按提示取消订阅。",
    "sub_cb3t": "方式 3：应用里向取消",
    "sub_cb3s": "勒 MAX课程表鸿蒙版个会员页，寻着管理订阅或者取消订阅入口，按提示操作。",
    "sub_cancelNote1": "请注意：光是卸载仔应用是勿会取消订阅个。卸载之后订阅还会继续自动续期，假使要停脱扣费，请按上底个方式先取消订阅。",
    "sub_cancelNote2": "取消之后假使要确认是勿是已经取消成功，可以按方式 1 或者方式 2 个路径，看看 MAX课程表个订阅状态搭仔到期日。",
    "sub_refundP": "退款请通过华为申请：勒华为应用市场“我个 > 订单/退款”里向提交，或者联系华为客服，按华为个规则处理。款项按华为个规则原路退回，对应个会员权益同时撤销。",
    "sub_minorsP1": "未满 18 周岁个未成年人开通主题会员，要由监护人决定并完成支付。监护人假使有疑问，请发邮件到<a href='#contact'>文末邮箱</a>联系开发者。",
    "sub_minorsP2": "未满 14 周岁儿童个个人信息保护说明，看<a href='../privacy/max-timetable/children/'>儿童个人信息保护说明</a>。",
    "sub_contactP": "买、续费或者取消碰着问题，请发邮件联系开发者，邮件里向请讲清爽碰着个问题；涉及华为订单个问题，请同时提供华为订单号。",
