    "ch_metaTitle": "MAX课程表儿童个人信息保护说明 — Sumiger",
    "ch_metaDesc": "MAX课程表勿会主动收集未满 14 周岁儿童个个人信息。搿份说明可以单独看。",
    "ch_intro": "搿份说明是拨未满 14 周岁儿童个监护人看个，讲 MAX课程表哪能对待儿童个人信息。搿页可以单独看。完整政策看 <a href='../'>MAX课程表隐私政策</a>。",
    "ch_scopeTitle": "适用范围",
    "ch_scopeP1": "搿份说明适用勒未满 14 周岁个儿童搭仔伊拉个监护人。未满 18 周岁个未成年人，请勒监护人指导下用搿个应用。",
    "ch_scopeP2": "MAX课程表是本地课程表工具，用来每日搭仔每周排课、作息设置，搭仔主题搭仔会员。应用呒没账号体系，勿需要登录。",
