    "ch_hb2s": "相册里向个照片，搭仔 PDF、TXT、DOC 文档，只有勒通过系统选择器主动选个辰光才会被访问，用来做课程表图片导入、DIY 背景或者课程表文件导入，并保存在设备上。",
    "ch_hb3t": "通知",
    "ch_hb3s": "通知权限只用来做本机课前提醒。提醒内容留勒设备上。",
