    "ch_hb4s": "假使涉及付费，由华为应用内支付（Huawei In-App Purchases，IAP）处理。开发者勿收集银行卡号。是勿是允许勒设备上完成购买，由监护人决定。",
    "ch_handleP3": "搿个版本勿涉及应用内广告或者个性化推荐。",
    "ch_handleP4": "应用勿会主动收集通讯录、精确位置或者传感器数据，也勿会为仔画像目的收集 IMEI 或者 OAID。",
    "ch_permLi2": "相册搭仔文件只勒通过系统选择器主动选照片或者文档个辰光访问。应用勿会勒呒没选个辰光扫描相册或者文件系统。",
    "ch_storeTitle": "存储搭仔删除",
    "ch_storeP": "信息保存在使用者个设备上，勒实现相应功能需要个期间里向保留，直到卸载应用或者清除应用数据。",
    "ch_shareP1": "开发者勿会出售儿童个人信息，也勿会为仔账号同步拿本地个课程、作息、偏好或者选个照片搭仔文档上传到开发者自家个服务器。",
    "ch_rightsTitle": "监护人个权利",
    "ch_rightsLi1": "查阅搭仔更正：勒应用里向编辑课程搭仔设置。",
    "ch_rightsLi2": "删除：卸载应用，或者清除应用数据。",
    "ch_rightsLi3": "咨询：用文末邮箱联系开发者，并讲明侬是监护人搭仔想了解个问题。",
    "ch_rightsP": "开发者呒办法从服务器导出课程内容，因为搿眼内容呒没上传到开发者自家个服务器。查阅、更正搭仔删除请勒设备上完成。",
