    "ch_updateP": "说明假使有变更，会更新搿只页面，并修改「更新日期」。请以搿只页面显示个日期为准。",

    "rts_metaTitle": "MAX课程表隐私权利 — Sumiger",
    "rts_metaDesc": "MAX课程表用户隐私权利说明：查阅、更正、删除本地数据个办法，搭仔哪能通过邮件行使权利。课程、作息搭仔偏好默认只保存在侬个设备上。",
    "rts_h1": "MAX课程表隐私权利",
    "rts_intro": "搿页讲侬对 MAX课程表处理个信息享有啥权利，搭仔哪能行使搿眼权利。MAX课程表呒没账号体系，勿需要登录；课程、作息、主题搭仔偏好默认只保存在侬个设备上，开发者呒没服务器副本。完整说明看<a href='../'>MAX课程表隐私政策</a>。",
    "rts_rLi1": "查阅搭仔更正：勒应用里向看看、编辑课程搭仔设置。",
    "rts_rLi2": "删除：卸载应用，或者清除应用数据。",
    "rts_rLi3": "停止使用：应用呒没账号，勿用登录；假使侬勿同意搿份政策或者勿想继续用，请停止用搿个应用，或者卸载应用去删除本地数据。",
    "rts_rLi4": "申诉搭仔咨询：假使侬对搿份政策或者应用处理信息个方式有疑问、异议或者申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，勒邮件里向讲明侬是本人还是监护人、涉及个问题搭仔希望哪能处理，开发者会通过邮件回复。",
    "rts_rNote": "开发者呒没搿眼内容个服务器副本，所以删除以侬设备上个卸载或者清除应用数据为准，开发者呒办法从服务器上头帮侬删除；查阅搭仔更正请勒设备上个应用里向完成。",
    "rts_howTitle": "哪能行使权利",
    "rts_howLi1": "查阅、更正：打开应用，勒课表页编辑相应课程，或者勒设置页修改作息搭仔偏好。",
    "rts_howLi2": "删除单项内容：勒应用里向删除相应课程。",
    "rts_howLi3": "删除全部本地数据：卸载应用；或者勒系统设置里向寻着 MAX课程表，清除应用数据。卸载或者清除数据之后，设备上个本地数据就被删除了，操作之前请自家确认是勿是需要保留课表内容。",
    "rts_howLi4": "联系开发者：假使要咨询、申诉，或者对上底个操作有疑问，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，写明涉及个问题搭仔希望哪能处理（查阅、更正、删除或者停止使用）。",
    "rts_childP1": "搿个应用勿会主动收集未满 14 周岁儿童个个人信息。未满 18 周岁个未成年人，请勒监护人指导下用。",
    "rts_childP2": "监护人申诉搭仔删除指引：监护人假使对儿童用搿个应用有疑问、异议或者申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，邮件标题请注明“监护人申诉”，并写明儿童年龄、涉及个问题搭仔希望哪能处理（查阅、更正、删除或者停止使用），开发者会通过邮件回复操作指引。",
    "rts_childP3": "删除本地数据个办法（请勒儿童个设备上操作）：勒应用里向删除相应课程；或者卸载应用，或者勒系统设置里向清除应用数据。开发者呒没服务器副本，呒办法远程看看、导出或者删除儿童设备上个数据，删除要由监护人勒设备上完成。",

