    "app_metaTitle": "MAX课程表 — Sumiger",
    "app_metaDesc": "MAX课程表是个本地课程表工具，用来排每日跟每周的课、设置作息，还有主题跟会员。",
    "app_devLine": "开发者 孙明威 / Sumiger",
    "app_intro": "MAX课程表是个本地课程表工具，用来排每日跟每周的课、设置作息，还有主题跟会员。课程、作息、主题跟语言偏好默认只保存在你的设备上，不会上传到开发者自己的服务器做账号同步。应用不曾有账号，也不需要登录。",
    "app_dlTitle": "下载",
    "app_dlHM": "下载安装包（鸿蒙，1.1.1，1.2 MB）",
    "app_dlHMNote": "個個安装包是华为应用市场正式签名版（.app），适合鸿蒙设备用。要是下载后提示装不上，请等应用市场审核通过后再从华为应用市场下载。",
    "app_dlAn": "下载安装包（安卓，1.1.1，45.4 MB）",
    "app_dlAnNote": "個個安装包是安卓版（.apk），适合安卓手机用，安装的时候要允许安装不晓得来源的应用。安卓版主题已经全部解锁，现在支持拍照导入课表（本地识别）。",
    "app_subTitle": "订阅",
    "app_subText": "鸿蒙版主题会员 ¥3/月，每月自动续期，通过华为应用内支付开通，随时可以取消。安卓版主题已经全部解锁，不涉及付费订阅。详情看<a href='../../subscription/'>订阅说明</a>。",
