    "wata_h1": "渡边记账",
    "wata_metaTitle": "渡边记账 — Sumiger",
    "wata_metaDesc": "渡边记账是个本地记账工具，用来手动记账、按日看收支，还有收支趋势跟分类统计。数据默认只保存在你的设备上，不绑定微信、支付宝账号。",
    "wata_intro": "渡边记账是个本地记账工具，用来手动记账、按日看收支，还有收支趋势跟分类统计。账本、分类跟偏好默认只保存在你的设备上，不会上传到开发者自己的服务器做账号同步。应用不曾有账号，也不需要登录，不绑定微信、支付宝账号。",
    "wata_authorTitle": "作者寄语",
    "wata_authorText": "渡边是日本的一个大姓，日本社会深陷通缩的时候，出现了一帮“渡边太太”。因为国情不一样，我们不能像“渡边太太”那样开源，不过我们可以用渡边记账来节流。",
    "wata_featTitle": "功能",
    "wata_featHome": "<strong>首页：</strong>左右滑切换列表跟日历。列表按日期分组，顶部可以换月份，显示当月收入、支出跟余额；日历按天显示结余，正数是绿色、负数是红色，点某天看当天明细。右下角加号可以记一笔：金额、收/支、分类、商户/对方、备注、支付方式。",
    "wata_featCharts": "<strong>图表：</strong>顶部切换饼状图跟折线图，两张图都能切换支出跟收入。饼状图按分类显示占比跟金额；折线图显示按日趋势，下头是日期、收入、支出、结余的表，带总计行。",
    "wata_featSettings": "<strong>设置：</strong>作者寄语、联系方式、隐私政策跟开发者个人网站。联系方式：<a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>。",
    "wata_expTitle": "实验功能（默认关闭）",
    "wata_expIntro": "下头两个功能是实验性的，默认关闭，打开后也只把结果放进“待确认”，由你逐条核对金额、改好分类，点“保存入账”才会写入账本。可能会漏记、错记，随时可能下线。",
    "wata_expImport": "<strong>账单导入：</strong>你自己从微信、支付宝官方入口导出账单文件（.csv），再分享给应用解析。微信账单只能导出最近三个月。解析结果去重后进“待确认”，不自动入账。",
    "wata_expListener": "<strong>通知监听（只有安卓）：</strong>只读微信跟支付宝的支付通知，在本机解析金额跟商户名，不存通知原文，验证码一律丢弃。需要在系统设置里由你亲自授予“通知使用权”，应用不能自己授权。",
    "wata_notDo": "不做：月预算、绑定微信/支付宝账号实时同步、读屏增强、截图识别、云同步、社区分享、图片上传。",
    "wata_dlTitle": "下载",
    "wata_dlHM": "下载安装包（鸿蒙，1.0.1，199 KB）",
    "wata_dlHMNote": "個個安装包是鸿蒙版（.app），适合鸿蒙设备用。应用市场审核通过后，也可以从华为应用市场下载。",
    "wata_dlAn": "下载安装包（安卓，1.0.0，7.4 MB）",
    "wata_dlAnNote": "個個安装包是安卓版（.apk），适合安卓手机用，安装的时候要允许安装不晓得来源的应用。",
    "wata_privTitle": "隐私",
    "wata_privText": "账本数据只存在你的设备上。实验功能打开前会再弹一次确认，说明读什么、存哪、咋个关；关闭后立刻停止读取，已经入账的不受影响。识别记录只留最近 24 小时、最多 50 条，可以一键清除。完整隐私政策看应用里面的隐私政策页。",
    "wata_privLink": "渡边记账隐私政策",
    "wata_termsLink": "渡边记账用户协议",

