    "sub_buyP1": "在鸿蒙版 MAX课程表里头，打开主题页或者会员页，点“开通主题会员”，在购买页确认价格（¥3/月）跟自动续期说明，勾上同意個份订阅说明后，在华为收银台确认付款就能开通。",
    "sub_buyP2": "购买页的同意选项默认是不勾的，要你自己勾。要是支付失败或者你在收银台取消支付，不会开通会员，也不会扣费。",
    "sub_cancelP1": "随时可以取消自动续期，取消不曾有啥额外条件。随便选下边一种方式：",
