    "sub_cancelNote1": "请注意：光卸载应用是不会取消订阅的。卸载后订阅还会继续自动续期，要想停扣费，请按上边的方式先取消订阅。",
    "sub_cancelNote2": "取消后要是想确认哿是已经取消成功，可以按方式 1 或者方式 2 的路径，看看 MAX课程表的订阅状态跟到期日。",
    "sub_refundP": "退款请通过华为申请：在华为应用市场“我的 > 订单/退款”里头提交，或者联系华为客服，按华为的规则处理。款项按华为的规则原路退回，对应的会员权益同时撤销。",
