    "papp_metaTitle": "MAX课程表隐私政策 — Sumiger",
    "papp_metaDesc": "MAX课程表的隐私政策。课程、作息跟偏好默认只保存在你的设备上。当前版本不涉及应用内广告或者个性化推荐。",
    "papp_pkgName": "包名",
    "papp_intro1": "個份政策说明本地课程表工具 MAX课程表咋个处理信息。它可以用来安排每日跟每周的课程、设置作息，还有用主题跟会员。应用不曾有账号体系，不需要登录。",
    "papp_intro2": "未满 14 周岁儿童的说明另外有单独页面：<a href='children/'>儿童个人信息保护说明</a>。個份政策里头也有一节可以在页里头查，看<a href='#children'>未成年人</a>。",
