    "papp_storeP": "上边讲的信息保存在你的设备上，在实现相应功能需要的期间里头保留，直到你卸载应用或者清除应用数据。",
    "papp_shareP1": "开发者不出售个人信息，也不会为账号同步把课程、作息、偏好或者你选的照片跟文档上传到开发者自己的服务器。",
    "papp_shareP2": "主题会员要是涉及付费，由华为应用内支付（Huawei In-App Purchases，IAP）处理。开发者不收集银行卡号。",
    "papp_shareP3": "法律法规有强制性要求的时候，开发者只在那个要求的范围里头处理。",
