    "papp_rightsP": "开发者不曾有個些内容的服务器副本，所以删除以你设备上的卸载或者清除应用数据为准。要是想咨询，请用<a href='#contact'>文末邮箱</a>。",
    "papp_childP1": "個個应用不主动收集未满 14 周岁儿童的个人信息。未满 18 周岁的未成年人，请在监护人指导下用。",
    "papp_childP2": "监护人可以用<a href='#contact'>文末邮箱</a>联系开发者。单独页面：<a href='children/'>儿童个人信息保护说明</a>。",
    "papp_updateP": "政策要是有变更，会更新個页，并修改「更新日期」。请以個页显示的日期为准。",
    "papp_relAll": "全部隐私政策",
    "wapp_metaTitle": "渡边记账隐私政策 — Sumiger",
    "wapp_metaDesc": "渡边记账的隐私政策。账本数据默认只保存在你的设备上，不会上传。",
    "wapp_h1": "渡边记账隐私政策",
    "wapp_intro1": "個份政策说明本地记账工具渡边记账咋个处理信息。它用来手动记账、按日看收支，还有看收支趋势跟分类统计。应用不曾有账号体系，不需要登录，不绑定任何支付账号。",
    "wapp_intro2": "实验功能（账单导入、通知监听）默认关闭，打开后也只把结果放进“待确认”，由你逐条核对后才会写入账本。相关说明看“实验功能”那节。",
    "wapp_tocInfo": "我倈处理个信息",
    "wapp_tocExp": "实验功能",
    "wapp_tocPerm": "权限",
    "wapp_tocNot": "当前版本不涉及",
    "wapp_tocStore": "存储跟保留",
    "wapp_tocShare": "共享、转让跟公开披露",
    "wapp_tocRights": "你的权利",
    "wapp_tocUpdate": "個份政策咋个更新",
    "wapp_infoP": "记账内容、分类跟偏好默认只保存在你的设备上，不会上传到开发者自己的服务器做账号同步。开发者不曾有個些内容的服务器副本。",
    "wapp_ib1t": "记账内容",
    "wapp_ib1s": "用来记录金额、收或支、分类、商户或对方、备注、支付方式跟日期。只保存在你的设备上。",
    "wapp_ib2t": "分类跟偏好",
    "wapp_ib2s": "用来在本机保存分类、显示跟语言设置。只保存在你的设备上。",
    "wapp_ib3t": "识别记录",
    "wapp_ib3s": "实验功能产生的识别结果说明，看“实验功能”那节。只保存在你的设备上。",
    "wapp_expP": "下头两项是实验功能，默认关闭。打开后结果只进“待确认”，由你逐条核对金额、改好分类，点“保存入账”才会写入账本。识别可能漏记或错记，功能随时可能调整或下线。",
    "wapp_exp1t": "账单导入",
    "wapp_exp1s": "只有你主动选账单文件（CSV）的时候，应用才会在本机解析里头的交易时间、类型、对方、商品、收或支、金额、支付方式、状态跟单号。文件不上传。微信账单只能导出最近三个月。支付宝账单表头不曾有用真实文件核对过，解析结果请逐条核对。",
    "wapp_exp2t": "通知监听（只有安卓）",
    "wapp_exp2s": "只读微信跟支付宝的支付通知，在本机解析金额跟商户名。验证码一律丢弃，长数字只留后四位，不保存通知原文。需要在系统设置里由你亲自授予通知使用权，应用不能自己授权。",
    "wapp_exp3t": "待确认跟识别记录",
    "wapp_exp3s": "导入跟通知的结果都先停在“待确认”，保存入账之前不会写入账本。识别记录只留最近 24 小时、最多 50 条，可以一键清除，超时或超量自动删除。",
    "wapp_permP": "应用只用功能实际需要的系统能力。",
    "wapp_permLi1": "通知使用权：只有你打开通知监听后才用，用来读微信跟支付宝的支付通知。",
    "wapp_permLi2": "文件访问：只在你通过系统选择器主动选账单文件的时候访问对应的文件。应用不会在你不曾选的时候扫描文件系统。",
    "wapp_notP1": "当前版本不涉及应用内广告或者个性化推荐，不接入第三方统计或者广告 SDK。",
    "wapp_notP2": "应用不主动收集通讯录、精确位置、短信内容或者传感器数据，也不为画像目的收集 IMEI 或者 OAID。",
    "wapp_storeP": "上边讲的信息保存在你的设备上，在实现相应功能需要的期间里头保留，直到你删除记录、卸载应用或者清除应用数据。识别记录只留最近 24 小时、最多 50 条。",
    "wapp_shareP1": "开发者不出售个人信息，也不会为账号同步把账本、分类、偏好或者识别记录上传到开发者自己的服务器。",
    "wapp_shareP2": "法律法规有强制性要求的时候，开发者只在那个要求的范围里头处理。",
    "wapp_rightsLi1": "查阅跟更正：在应用里头查看跟编辑记账内容跟设置。",
    "wapp_rightsLi2": "删除：删除单条记录，或者卸载应用、清除应用数据。",
    "wapp_rightsP": "开发者不曾有個些内容的服务器副本，所以删除以你设备上的操作为准。要是想咨询，请用<a href='#contact'>文末邮箱</a>。",
    "wapp_childP1": "個個应用不主动收集未满 14 周岁儿童的个人信息。未满 18 周岁的未成年人，请在监护人同意跟指导下用。",
    "wapp_updateP": "政策要是有变更，会更新個页，并修改「更新日期」。请以個页显示的日期为准。",
