    "wterms_h1": "渡边记账用户协议",
    "wterms_intro1": "個份协议是你跟开发者孙明威（Sumiger）之间关于用渡边记账的约定。用個个应用就是说你已经读过并且同意個份协议。要是你不同意，请不要用。",
