    "wterms_tocFee": "费用",
    "wterms_tocDisclaim": "免责",
    "wterms_tocIP": "知识产权",
    "wterms_tocChange": "变更跟终止",
    "wterms_tocLaw": "法律跟联系",
    "wterms_serviceP": "渡边记账是个本地记账工具，提供手动记账、按日看收支、收支趋势跟分类统计。实验功能包括账单导入跟通知监听，看“实验功能”那节。",
    "wterms_serviceLi1": "首页：列表跟日历两种视图，查看当月收入、支出、余额跟每天结余。",
    "wterms_serviceLi2": "图表：饼状图跟折线图，都能切换支出跟收入看。",
    "wterms_serviceLi3": "设置：作者寄语、联系方式、隐私政策跟开发者个人网站。",
    "wterms_dataP1": "個个应用不曾有账号体系，不需要登录，不绑定任何支付账号。",
    "wterms_dataP2": "账本数据默认只保存在你的设备上，开发者不曾有服务器副本。请自己好好保管。因为卸载应用、清除应用数据、换设备或者丢了设备、设备故障造成的数据丢失，开发者不承担责任。",
    "wterms_expP1": "账单导入跟通知监听是实验功能，默认关闭。打开后结果只进“待确认”，由你逐条核对金额、改好分类，点“保存入账”才会写入账本。",
    "wterms_expP2": "识别可能漏记或错记，功能随时可能调整或下线。开发者对识别结果的准确性不负责，请以你核对后的入账记录为准。",
    "wterms_rulesLi1": "不能拿個个应用做任何违法用途，包括但不限于记录违法交易、洗钱、逃税。",
    "wterms_rulesLi2": "不能对应用做逆向工程、破解、篡改，或者干扰它正常运行。",
    "wterms_rulesLi3": "不能冒充开发者，或者以开发者的名义对外提供服务。",
    "wterms_feeP": "個个应用现在全部免费，不收任何费用。以后要是有收费功能，会提前说明，由你自己决定开不开通，不会在你不晓得的情况下扣费。",
    "wterms_disP1": "個个应用只做记账记录，不构成财务、税务、投资或者法律建议。",
    "wterms_disP2": "因为设备故障、系统问题或者实验功能识别错误造成的记录问题，请以你的原始凭证为准，开发者不承担相应责任。",
    "wterms_ipP": "個个应用跟它的内容（包括名称、界面、文字说明）的知识产权归开发者所有。没有许可，不能复制、分发、修改或者用于商业用途。",
    "wterms_changeP": "开发者可以根据需要更新版本、调整或者下线功能，更新内容会在应用里头或者网站说明。你可以随时停止使用并卸载应用。",
    "wterms_minorsP": "未满 14 周岁请在监护人同意跟指导下用；未满 18 周岁的未成年人，请在监护人指导下用。",
    "wterms_lawP1": "個份协议适用中华人民共和国法律。",
    "wterms_lawP2": "因为個份协议产生的争议，双方应该先友好协商解决。",
