    "ch_metaTitle": "MAX课程表儿童个人信息保护说明 — Sumiger",
    "ch_metaDesc": "MAX课程表不主动收集未满 14 周岁儿童的个人信息。個份说明可以单独看。",
    "ch_intro": "個份说明是给未满 14 周岁儿童的监护人看的，说明 MAX课程表咋个对待儿童个人信息。個页可以单独看。完整政策看 <a href='../'>MAX课程表隐私政策</a>。",
    "ch_scopeTitle": "适用范围",
    "ch_scopeP1": "個份说明适用于未满 14 周岁的儿童跟他倈的监护人。未满 18 周岁的未成年人，请在监护人指导下用個個应用。",
    "ch_scopeP2": "MAX课程表是本地课程表工具，用来每日跟每周排课、作息设置，还有主题跟会员。应用不曾有账号体系，不需要登录。",
    "ch_handleTitle": "我倈咋个对待儿童个人信息",
    "ch_handleP1": "個個应用不主动收集未满 14 周岁儿童的个人信息。",
    "ch_handleP2": "儿童或者监护人要是用课程表，相关内容按下边的方式留在设备上。开发者不曾有個些内容的服务器副本。",
    "ch_hb1t": "课程、作息、主题跟语言偏好",
    "ch_hb1s": "默认只保存在设备上，不会上传到开发者自己的服务器做账号同步。",
    "ch_hb2t": "照片跟文档",
    "ch_hb2s": "相册里头的照片，还有 PDF、TXT、DOC 文档，只有在通过系统选择器主动选的时候才会被访问，用来做课程表图片导入、DIY 背景或者课程表文件导入，并保存在设备上。",
    "ch_hb3t": "通知",
    "ch_hb3s": "通知权限只用来做本机课前提醒。提醒内容留在设备上。",
    "ch_hb4t": "主题会员",
    "ch_hb4s": "要是涉及付费，由华为应用内支付（Huawei In-App Purchases，IAP）处理。开发者不收集银行卡号。是不是允许在设备上完成购买，由监护人决定。",
    "ch_handleP3": "当前版本不涉及应用内广告或者个性化推荐。",
    "ch_handleP4": "应用不主动收集通讯录、精确位置或者传感器数据，也不为画像目的收集 IMEI 或者 OAID。",
    "ch_permLi2": "相册跟文件只在通过系统选择器主动选照片或者文档的时候访问。应用不会在没选的时候扫描相册或者文件系统。",
    "ch_storeTitle": "存储跟删除",
    "ch_storeP": "信息保存在使用者的设备上，在实现相应功能需要的期间里头保留，直到卸载应用或者清除应用数据。",
    "ch_shareP1": "开发者不出售儿童个人信息，也不会为账号同步把本地的课程、作息、偏好或者选的照片跟文档上传到开发者自己的服务器。",
    "ch_rightsTitle": "监护人的权利",
    "ch_rightsLi1": "查阅跟更正：在应用里头编辑课程跟设置。",
    "ch_rightsLi2": "删除：卸载应用，或者清除应用数据。",
    "ch_rightsLi3": "咨询：用文末邮箱联系开发者，并说明你是监护人还有想了解的问题。",
    "ch_rightsP": "开发者没办法从服务器导出课程内容，因为個些内容不曾上传到开发者自己的服务器。查阅、更正跟删除请在设备上完成。",
    "ch_updateTitle": "個份说明咋个更新",
    "ch_updateP": "说明要是有变更，会更新個页，并修改「更新日期」。请以個页显示的日期为准。",

    "rts_metaTitle": "MAX课程表隐私权利 — Sumiger",
    "rts_metaDesc": "MAX课程表用户隐私权利说明：查阅、更正、删除本地数据的方法，还有咋个通过邮件行使权利。课程、作息跟偏好默认只保存在你的设备上。",
    "rts_h1": "MAX课程表隐私权利",
    "rts_intro": "個页说明你对 MAX课程表处理的信息享有的权利，还有咋个行使個些权利。MAX课程表不曾有账号体系，不需要登录；课程、作息、主题跟偏好默认只保存在你的设备上，开发者不曾有服务器副本。完整说明看<a href='../'>MAX课程表隐私政策</a>。",
    "rts_rLi1": "查阅跟更正：在应用里头看看、编辑课程跟设置。",
    "rts_rLi2": "删除：卸载应用，或者清除应用数据。",
    "rts_rLi3": "停止使用：应用不曾有账号，不用登录；要是你不同意個份政策或者不想继续用，请停用個個应用，或者卸载应用来删除本地数据。",
    "rts_rLi4": "申诉跟咨询：要是你对個份政策或者应用处理信息的方式有疑问、异议或者申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，在邮件里头说明你是本人还是监护人、涉及的问题还有希望咋个处理，开发者会通过邮件回复。",
    "rts_rNote": "开发者不曾有個些内容的服务器副本，所以删除以你设备上的卸载或者清除应用数据为准，开发者没办法从服务器上头帮你删除；查阅跟更正请在设备上的应用里头完成。",
    "rts_howTitle": "咋个行使权利",
    "rts_howLi1": "查阅、更正：打开应用，在课表页编辑相应的课程，或者在设置页修改作息跟偏好。",
    "rts_howLi2": "删除单项内容：在应用里头删除相应的课程。",
    "rts_howLi3": "删除全部本地数据：卸载应用；或者在系统设置里头尋到 MAX课程表，清除应用数据。卸载或者清除数据后，设备上的本地数据就被删除了，操作前请自己确认是不是需要保留课表内容。",
    "rts_howLi4": "联系开发者：要是想咨询、申诉，或者对上边的操作有疑问，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，写明涉及的问题还有希望咋个处理（查阅、更正、删除或者停止使用）。",
    "rts_childP1": "個個应用不主动收集未满 14 周岁儿童的个人信息。未满 18 周岁的未成年人，请在监护人指导下用。",
    "rts_childP2": "监护人申诉跟删除指引：监护人要是对儿童用個個应用有疑问、异议或者申诉，请发邮件到 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>，邮件标题请注明“监护人申诉”，并写明儿童年龄、涉及的问题还有希望咋个处理（查阅、更正、删除或者停止使用），开发者会通过邮件回复操作指引。",
    "rts_childP3": "删除本地数据的方法（请在儿童的设备上操作）：在应用里头删除相应的课程；或者卸载应用，或者在系统设置里头清除应用数据。开发者不曾有服务器副本，没办法远程查看、导出或者删除儿童设备上的数据，删除要由监护人在设备上完成。",

