    "sub_relHome": "ホーム",

    "priv_metaTitle": "プライバシーポリシー — Sumiger",
    "priv_metaDesc": "公開済みのアプリのプライバシーポリシー。このサイトでは、訪問者の IP アドレスとアクセス時刻を記録し、アクセス数を集計しています。",
    "priv_lede": "公開済みのアプリのプライバシーポリシーを一覧で掲載しています。",
    "priv_appTitle": "MAX課程表プライバシーポリシー",
