    "rts_rNote": "개발자는 이러한 내용의 서버 사본을 보유하고 있지 않으므로 삭제는 사용자의 기기에서 앱을 삭제하거나 앱 데이터를 지우는 것으로 이루어지며, 개발자가 서버에서 대신 삭제해 드릴 수 없습니다. 조회와 정정은 기기의 앱 안에서 완료해 주세요.",
    "rts_howTitle": "권리 행사 방법",
    "rts_howLi1": "조회, 정정: 앱을 열고 시간표 페이지에서 해당 수업을 편집하거나 설정 페이지에서 생활 리듬과 설정을 변경해 주세요.",
    "rts_howLi2": "개별 내용 삭제: 앱 안에서 해당 수업을 삭제해 주세요.",
    "rts_howLi3": "모든 로컬 데이터 삭제: 앱을 삭제해 주세요. 또는 시스템 설정에서 MAX 시간표를 찾아 앱 데이터를 지우세요. 삭제하거나 데이터를 지운 뒤에는 기기의 로컬 데이터가 삭제됩니다. 조작하기 전에 시간표 내용을 보관할 필요가 있는지 직접 확인해 주세요.",
    "rts_howLi4": "개발자에게 연락: 문의, 이의 제기, 또는 위 조작에 대해 궁금한 점이 있으면 <a href='mailto:MAXschedule@outlook.com'>MAXschedule@outlook.com</a>으로 메일을 보내 주세요. 문제 내용과 어떻게 처리하기를 원하는지(조회, 정정, 삭제, 이용 중단)를 적어 주세요.",
